import { randomUUID } from "node:crypto";
import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";

const filePath = process.env.BOOKS_DATA_FILE || join(process.cwd(), "data", "books.json");
let writeQueue = Promise.resolve();

export async function getBooks() {
  try {
    const contents = await readFile(filePath, "utf8");
    const books = JSON.parse(contents);
    if (!Array.isArray(books)) throw new Error("Books file must contain an array");
    return books;
  } catch (error) {
    if (error.code === "ENOENT") return [];
    throw error;
  }
}

export async function getBook(id) {
  return (await getBooks()).find((book) => book.id === id) ?? null;
}

// Serialize mutations so two nearly simultaneous submissions cannot lose a book.
function changeBooks(update) {
  const operation = writeQueue.then(async () => {
    const books = await getBooks();
    const result = update(books);
    await mkdir(dirname(filePath), { recursive: true });
    const temporaryFile = `${filePath}.${randomUUID()}.tmp`;
    await writeFile(temporaryFile, JSON.stringify(books, null, 2) + "\n", "utf8");
    await rename(temporaryFile, filePath);
    return result;
  });
  writeQueue = operation.then(() => {}, () => {});
  return operation;
}

export async function addBook({ title, author, notes }) {
  return changeBooks((books) => {
    const book = {
      id: randomUUID(),
      title,
      author,
      notes,
      addedAt: new Date().toISOString(),
      finishedAt: null,
    };
    books.unshift(book);
    return book;
  });
}

export async function finishBook(id) {
  return changeBooks((books) => {
    const book = books.find((item) => item.id === id);
    if (!book) return false;
    if (!book.finishedAt) book.finishedAt = new Date().toISOString();
    return true;
  });
}

