"use server";

import { revalidatePath } from "next/cache";
import { addBook, finishBook } from "../lib/books";

export async function createBook(_previousState, formData) {
  const title = String(formData.get("title") ?? "").trim();
  const author = String(formData.get("author") ?? "").trim();
  const notes = String(formData.get("notes") ?? "").trim();

  if (!title || !author) {
    return { error: "Please enter a title and author.", savedId: null };
  }
  if (title.length > 200 || author.length > 200 || notes.length > 10000) {
    return { error: "One of the fields is too long.", savedId: null };
  }

  try {
    const book = await addBook({ title, author, notes });
    revalidatePath("/");
    return { error: null, savedId: book.id };
  } catch {
    return { error: "Could not save your book. Please try again.", savedId: null };
  }
}

export async function markFinished(formData) {
  const id = formData.get("id");
  if (typeof id !== "string" || !id) return;
  const found = await finishBook(id);
  if (found) {
    revalidatePath("/");
    revalidatePath(`/books/${id}`);
  }
}

