export default function BookCover({ book, large = false }) {
  const palette = Array.from(book.title).reduce((sum, char) => sum + char.charCodeAt(0), 0) % 5;
  return (
    <div className={`book-cover cover-${palette}${large ? " book-cover-large" : ""}`} aria-hidden="true">
      <div className="cover-rule" />
      <span className="cover-letter">{book.title.charAt(0).toUpperCase()}</span>
      <div className="cover-bottom"><span>FOLIO LIBRARY</span><span>✳</span></div>
    </div>
  );
}

