"use client";

import { useActionState, useEffect, useRef } from "react";
import { createBook } from "../app/actions";
import { ArrowRight, Plus } from "./icons";

export default function AddBookForm() {
  const [state, formAction, pending] = useActionState(createBook, { error: null, savedId: null });
  const formRef = useRef(null);

  useEffect(() => {
    if (state.savedId) formRef.current?.reset();
  }, [state.savedId]);

  return (
    <aside className="add-panel" id="add-book" aria-labelledby="add-heading">
      <div className="panel-icon"><Plus size={20} /></div>
      <div className="panel-kicker">MAKE ROOM FOR A NEW STORY</div>
      <h2 id="add-heading">Add a book<span className="heading-period">.</span></h2>
      <p className="panel-description">The next chapter starts here. Add what you&apos;re reading and jot down anything you want to remember.</p>
      <form ref={formRef} action={formAction} className="add-form">
        <div className="form-field">
          <label htmlFor="title">Book title <span aria-hidden="true">*</span></label>
          <input id="title" name="title" type="text" placeholder="e.g. The Midnight Library" required maxLength={200} />
        </div>
        <div className="form-field">
          <label htmlFor="author">Author <span aria-hidden="true">*</span></label>
          <input id="author" name="author" type="text" placeholder="e.g. Matt Haig" required maxLength={200} />
        </div>
        <div className="form-field">
          <label htmlFor="notes">Your notes <span className="optional">(optional)</span></label>
          <textarea id="notes" name="notes" rows={4} placeholder="A thought, a quote, a reason you picked it up..." maxLength={10000} />
        </div>
        {state.error && <p className="form-message error" role="alert">{state.error}</p>}
        {state.savedId && !state.error && <p className="form-message success" role="status">Added to your reading list.</p>}
        <button className="primary-button" type="submit" disabled={pending}>
          {pending ? "Adding book..." : "Add to my books"}<ArrowRight size={18} />
        </button>
      </form>
      <p className="panel-footnote">No accounts, no fuss. Just your books.</p>
    </aside>
  );
}

