import Link from "next/link";
import { markFinished } from "../app/actions";
import BookCover from "./book-cover";
import { ArrowRight, Check } from "./icons";

export default function BookCard({ book }) {
  const finished = Boolean(book.finishedAt);
  return (
    <article className="book-card">
      <Link href={`/books/${book.id}`} className="cover-link" tabIndex={-1} aria-hidden="true"><BookCover book={book} /></Link>
      <div className="book-card-body">
        <div className="book-card-topline">{finished ? "FINISHED" : "CURRENTLY READING"}</div>
        <h3><Link href={`/books/${book.id}`}>{book.title}</Link></h3>
        <p className="book-author">by {book.author}</p>
        {book.notes && <p className="book-snippet">{book.notes}</p>}
        <div className="book-card-actions">
          <Link href={`/books/${book.id}`} className="text-link">View book <ArrowRight size={16} /></Link>
          {!finished && <form action={markFinished}><input type="hidden" name="id" value={book.id} /><button className="finish-button" type="submit"><Check size={15} /> Mark finished</button></form>}
        </div>
      </div>
    </article>
  );
}

