"use client";

import { useState } from "react";
import { LinkIcon } from "./icons";

export default function CopyLink() {
  const [message, setMessage] = useState("Copy book link");
  async function copy() {
    try {
      await navigator.clipboard.writeText(window.location.href);
      setMessage("Link copied!");
    } catch {
      setMessage("Copy the URL from your address bar");
    }
  }
  return <button type="button" className="secondary-button" onClick={copy}><LinkIcon /><span aria-live="polite">{message}</span></button>;
}

