import AddBookForm from "../components/add-book-form";
import BookCard from "../components/book-card";
import { BookIcon } from "../components/icons";
import { getBooks } from "../lib/books";

export const dynamic = "force-dynamic";

function BookSection({ title, number, books, finished }) {
  return (
    <section className="book-section" aria-label={title}>
      <div className="section-heading">
        <div className="section-heading-main"><span className={`section-marker ${finished ? "marker-finished" : ""}`} /><h2>{title}</h2><span className="section-count">{number}</span></div>
        <span className="section-aside">{finished ? "THE STORIES THAT STAY" : "THE STORIES IN PROGRESS"}</span>
      </div>
      {books.length ? (
        <div className="book-list">{books.map((book) => <BookCard key={book.id} book={book} />)}</div>
      ) : (
        <div className="empty-state">
          <div className="empty-icon"><BookIcon size={27} /></div>
          <div><h3>{finished ? "A blank page, for now." : "Your next read belongs here."}</h3><p>{finished ? "When you finish a book, it will find a home on this shelf." : "Add a book with the form, and your reading list will take shape."}</p></div>
        </div>
      )}
    </section>
  );
}

export default async function HomePage() {
  const books = await getBooks();
  const current = books.filter((book) => !book.finishedAt);
  const finished = books.filter((book) => book.finishedAt).sort((a, b) => b.finishedAt.localeCompare(a.finishedAt));

  return (
    <main className="container home-page">
      <div className="page-intro">
        <div className="eyebrow"><span className="eyebrow-line" /> YOUR PERSONAL LIBRARY</div>
        <h1>A good place to keep<br /><em>good stories.</em></h1>
        <p>A little home for the books you&apos;re reading, the ones you&apos;ve loved, and the thoughts you want to keep.</p>
      </div>
      <div className="home-grid">
        <div className="library-column">
          <div className="library-overview">
            <div><span className="overview-label">YOUR SHELVES</span><h2>My library<span className="heading-period">.</span></h2></div>
            <div className="stats"><div><strong>{current.length.toString().padStart(2, "0")}</strong><span>Reading</span></div><span className="stats-divider" /><div><strong>{finished.length.toString().padStart(2, "0")}</strong><span>Finished</span></div></div>
          </div>
          <BookSection title="Currently reading" number={current.length} books={current} />
          <BookSection title="Finished books" number={finished.length} books={finished} finished />
        </div>
        <AddBookForm />
      </div>
    </main>
  );
}

