import Link from "next/link";
import { notFound } from "next/navigation";
import { markFinished } from "../../actions";
import BookCover from "../../../components/book-cover";
import CopyLink from "../../../components/copy-link";
import { ArrowLeft, Check } from "../../../components/icons";
import { getBook } from "../../../lib/books";

export const dynamic = "force-dynamic";

export async function generateMetadata({ params }) {
  const { id } = await params;
  const book = await getBook(id);
  return { title: book ? `${book.title} by ${book.author}` : "Book not found" };
}

export default async function BookPage({ params }) {
  const { id } = await params;
  const book = await getBook(id);
  if (!book) notFound();
  const finished = Boolean(book.finishedAt);

  return (
    <main className="container detail-page">
      <Link className="back-link" href="/"><ArrowLeft size={17} /> Back to my library</Link>
      <div className="detail-layout">
        <div className="detail-cover-wrap"><BookCover book={book} large /></div>
        <div className="detail-content">
          <div className="detail-eyebrow"><span className={`section-marker ${finished ? "marker-finished" : ""}`} /> {finished ? "FINISHED BOOK" : "CURRENTLY READING"}</div>
          <h1>{book.title}</h1>
          <p className="detail-author">by <strong>{book.author}</strong></p>
          <div className="detail-rule" />
          <div className="detail-meta"><span>ADDED TO LIBRARY</span><strong>{new Date(book.addedAt).toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" })}</strong></div>
          {finished && <div className="detail-meta"><span>FINISHED</span><strong>{new Date(book.finishedAt).toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" })}</strong></div>}
          <div className="detail-rule" />
          <section className="notes-section"><div className="notes-kicker">MARGINALIA / YOUR THOUGHTS</div><h2>Notes<span className="heading-period">.</span></h2>{book.notes ? <p className="notes-text">{book.notes}</p> : <p className="notes-empty">No notes for this book yet.</p>}</section>
          <div className="detail-actions">
            {!finished && <form action={markFinished}><input type="hidden" name="id" value={book.id} /><button className="primary-button" type="submit"><Check size={18} /> Mark as finished</button></form>}
            <CopyLink />
          </div>
        </div>
      </div>
    </main>
  );
}

