@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=DM+Serif+Display:ital@0;1&display=swap');

:root { color-scheme: light; --paper: #faf8f4; --white: #fffefa; --ink: #252923; --muted: #777c72; --line: #e9e7df; --accent: #ad6551; --green: #60776b; }
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body { margin: 0; background: var(--paper); color: var(--ink); font-family: 'DM Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; -webkit-font-smoothing: antialiased; }
a { color: inherit; text-decoration: none; }
button, input, textarea { font: inherit; }
button { cursor: pointer; }
button:disabled { cursor: wait; opacity: .65; }
:focus-visible { outline: 3px solid #bd836c; outline-offset: 3px; }
.container { width: min(1152px, calc(100% - 80px)); margin-inline: auto; }
.site-header { border-bottom: 1px solid var(--line); background: rgba(255,254,250,.5); }
.header-inner { min-height: 82px; display: flex; align-items: center; justify-content: space-between; gap: 20px; }
.brand { display: inline-flex; gap: 12px; align-items: center; font-family: 'DM Serif Display', Georgia, serif; font-size: 31px; letter-spacing: -.04em; line-height: 1; }
.brand-period, .heading-period { color: var(--accent); }
