import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { tmpdir } from "node:os";

let directory;
let booksFile;

beforeEach(async () => {
  directory = await mkdtemp(join(tmpdir(), "folio-books-"));
  booksFile = join(directory, "nested", "books.json");
  process.env.BOOKS_DATA_FILE = booksFile;
  vi.resetModules();
});

afterEach(async () => {
  delete process.env.BOOKS_DATA_FILE;
  await rm(directory, { recursive: true, force: true });
});

describe("JSON book storage", () => {
  it("saves books across module reloads and marks a book finished", async () => {
    const library = await import("./books.js");
    expect(await library.getBooks()).toEqual([]);
    const book = await library.addBook({ title: "Dune", author: "Frank Herbert", notes: "A favorite." });
    expect(book.finishedAt).toBeNull();
    expect(await library.finishBook(book.id)).toBe(true);
    expect(await library.finishBook(book.id)).toBe(true);

    vi.resetModules();
    const reloaded = await import("./books.js");
    expect((await reloaded.getBook(book.id)).notes).toBe("A favorite.");
    expect((await reloaded.getBook(book.id)).finishedAt).toBeTruthy();
    expect(JSON.parse(await readFile(booksFile, "utf8"))).toHaveLength(1);
  });

  it("keeps simultaneous additions and does not erase invalid JSON", async () => {
    const library = await import("./books.js");
    await Promise.all(Array.from({ length: 8 }, (_, index) => library.addBook({ title: `Book ${index}`, author: "Author", notes: "" })));
    expect(await library.getBooks()).toHaveLength(8);
    expect(await library.finishBook("missing")).toBe(false);

    await writeFile(booksFile, "not json", "utf8");
    await expect(library.getBooks()).rejects.toThrow();
    await expect(library.addBook({ title: "Another", author: "Author", notes: "" })).rejects.toThrow();
    expect(await readFile(booksFile, "utf8")).toBe("not json");
  });
});

