node --input-type=module <<'NODE'
import { readFile } from 'node:fs/promises';
const base = 'http://localhost:3057';
function postForm(html, formPattern, fields) {
  const form = html.match(formPattern)?.[0];
  if (!form) throw new Error('Form not found');
  const data = new FormData();
  for (const input of form.match(/<input[^>]*type="hidden"[^>]*>/g) ?? []) {
    const name = input.match(/name="([^"]+)"/)?.[1];
    const value = input.match(/value="([^"]*)"/)?.[1] ?? '';
    if (name) data.set(name, value.replaceAll('&quot;', '"').replaceAll('&amp;', '&'));
  }
  for (const [key, value] of Object.entries(fields)) data.set(key, value);
  return fetch(base + '/', { method: 'POST', body: data });
}
const home = await (await fetch(base)).text();
const added = await postForm(home, /<form class="add-form"[\s\S]*?<\/form>/, { title: 'Action Test Book', author: 'Action Author', notes: 'Notes from a real form post.' });
console.log('Add form POST:', added.status);
const updated = await (await fetch(base)).text();
console.log('New book visible on home:', updated.includes('Action Test Book'));
const data = JSON.parse(await readFile('/tmp/folio-http-check-books.json', 'utf8'));
const id = data.find(book => book.title === 'Action Test Book')?.id;
if (!id) throw new Error('Add action did not save book');
const finishForm = updated.match(new RegExp(`<form[^>]*>[\\s\\S]*?name="id" value="${id}"[\\s\\S]*?<\\/form>`))?.[0];
if (!finishForm) throw new Error('Finish form not found');
const finished = await postForm(finishForm, /<form[\s\S]*?<\/form>/, {});
console.log('Finish form POST:', finished.status);
const detail = await (await fetch(base + '/books/' + id)).text();
console.log('Finish action visible on detail:', detail.includes('FINISHED BOOK'));
NODE

